function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(text,fn,cls='quiet'){const b=el('button',text,cls);b.type='button';b.addEventListener('click',event=>{try{Promise.resolve(fn(event)).catch(error=>message(error.message));}catch(error){message(error.message);}});return b;}
function field(label,id,value='',multiline=false,max=6000){const wrap=el('div',undefined,'field'),l=el('label',label),input=el(multiline?'textarea':'input');l.htmlFor=id;input.id=id;input.name=id;input.value=value;input.maxLength=max;input.addEventListener('input',()=>input.setCustomValidity(''));if(multiline)input.rows=3;wrap.append(l,input);return {wrap,input};}
function message(text){document.querySelector('#status').textContent=text;}
function focusHeading(){main.querySelector('h1,h2')?.focus();}
function heading(text,level=1){const h=el(`h${level}`,text);h.tabIndex=-1;return h;}
function clear(){main.replaceChildren();main.className='';}
function showModal(title,nodes){document.querySelector('#modal-title').textContent=title;content.replaceChildren(...nodes);modal.showModal();}
function actions(...nodes){const n=el('div',undefined,'actions');n.append(...nodes);return n;}
function download(text,name,type){if(new TextEncoder().encode(text).length>MAX_BYTES&&type==='application/json'){message('O backup excede 2 MB. Exporte as investigações individualmente.');return;}const url=URL.createObjectURL(new Blob([text],{type})),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function save(){if(!current)return Promise.resolve();clearTimeout(saveTimer);const generation=++saveGeneration;const snapshot=structuredClone(current);snapshot.updatedAt=new Date().toISOString();current.updatedAt=snapshot.updatedAt;const target=current.id;const state=document.querySelector('#save-state');if(state)state.textContent='Salvando…';saveQueue=saveQueue.catch(()=>{}).then(()=>db.putCheck(snapshot));saveQueue.then(()=>{if(current?.id===target&&generation===saveGeneration){const n=document.querySelector('#save-state');if(n)n.textContent='Salvo neste dispositivo';}},error=>{message(`Não foi possível salvar. Exporte seu registro agora. ${error.message}`);const n=document.querySelector('#save-state');if(n)n.textContent='Falha ao salvar';document.querySelector('#status').append(button('Exportar rascunho agora',()=>exportsFor(current)));});return saveQueue;}
function scheduleSave(){saveGeneration++;clearTimeout(saveTimer);saveTimer=setTimeout(()=>save(),250);const n=document.querySelector('#save-state');if(n)n.textContent='Alterações pendentes';}
async function flush(){clearTimeout(saveTimer);if(current)await save();else await saveQueue;}
function localNote(){const n=el('p','Busca neste dispositivo, em um acervo pequeno de fontes verificadas. Sua frase não é enviada a um buscador.','small');const d=el('details'),s=el('summary','O que o acervo cobre?');d.append(s,el('p','HTTPS e Wi-Fi, modo anônimo, efeito estufa, gráficos, correlação e causalidade, Lua e riscos de IA generativa. Sete páginas institucionais, em inglês; paráfrases em português. Conferência editorial em 01/10/2026. Não é uma busca ao vivo na internet.'));return [n,d];}
function supportBar(){const n=el('div',undefined,'support');const state=el('span','Salvando…','small');state.id='save-state';n.append(state,button('Exportar registro',()=>exportsFor(current)),button('Nova investigação',async()=>{await flush();current=null;home();focusHeading();}));return n;}
function home(){clear();main.className='home';main.append(el('p','ANTES DE ACEITAR OU COMPARTILHAR','eyebrow'),heading('O que você quer colocar à prova?'),el('p','Alguém disse uma coisa. Parece convincente. Encontre razões para examiná-la.','lead'));
 const form=el('form'),f=field('Sua afirmação ou pequeno texto','claim-input',current?.input||'',true);f.input.placeholder='Por exemplo: todo site com HTTPS é confiável.';f.input.required=true;f.input.rows=4;
 f.input.addEventListener('input',()=>{if(!current)current=newCheck();current.input=f.input.value;current.claim='';current.result=null;current.decision='';current.reason='';current.unavailable=[];scheduleSave();});
 const submit=el('button','Investigar','primary');submit.type='submit';form.append(f.wrap,submit);form.addEventListener('submit',async event=>{event.preventDefault();if(!f.input.value.trim()){f.input.setCustomValidity('Escreva uma frase para investigar.');f.input.reportValidity();return;}f.input.setCustomValidity('');if(!current)current=newCheck(f.input.value);current.input=f.input.value;try{await save();}catch{}await interpret();});main.append(form);
 const ex=el('div',undefined,'examples');ex.append(el('p','Experimente uma pergunta de partida:','small'));for(const text of examples)ex.append(button(text,()=>{if(!current)current=newCheck();f.input.setCustomValidity('');current.input=text;current.claim='';current.result=null;current.decision='';current.reason='';current.unavailable=[];f.input.value=text;scheduleSave();f.input.focus();},'example'));main.append(ex,...localNote());const owl=el('div',undefined,'owl-note'),img=el('img');img.src='assets/owl.webp';img.alt='';img.width=56;img.height=56;owl.append(img,el('p','A resposta parece boa. Como você sabe?'));main.append(owl);
 const state=el('p',current?'Salvando…':'O rascunho será salvo neste dispositivo.','small');state.id='save-state';main.append(state);if(current)save();
}
async function loadEngine(){return engine??=await import(`./search.js?attempt=${loadAttempt++}`);}
async function interpret(){const target=current?.id;try{const s=await loadEngine();if(current?.id!==target)return;const choices=s.candidates(current.input);const kind=s.suggestKind(current.input);if(choices.length>1||kind!=='fact'){interpretScreen(choices,kind);return;}current.claim=current.input.trim();current.kind='fact';await investigate();}catch(error){if(current?.id===target)searchFailure(error);}}
