 if(r.evidence.length){main.append(heading('O que sustenta ou desafia a afirmação',2),el('p','Estes trechos foram aproximados pelo assunto. A relação com sua frase depende do contexto.','small'));const origins=new Set(r.evidence.map(e=>e.sourceId));if(origins.size<r.evidence.length)main.append(el('p','Há trechos da mesma origem. Eles se complementam; não são confirmações independentes.','notice'));
 for(const [n,e] of r.evidence.entries()){const card=el('article',undefined,'evidence');card.id='evidence-'+e.id;card.append(el('p',`${String(n+1).padStart(2,'0')} · ${e.source.author}`,'eyebrow'),heading(e.relevance,3),el('p',e.passage));const a=el('a','Abrir fonte original ↗','source-link');a.href=e.source.url;a.target='_blank';a.rel='noopener noreferrer';card.append(a);const d=el('details');d.append(el('summary','Contexto, datas e limitações'),el('p',`Título original: ${e.source.title}`),el('p',`Paráfrase editorial, não citação literal. Localize na página: ${e.section}`),el('p',`Publicação: ${e.source.published}. Atualização: ${e.source.updated||'não informada'}. Consulta editorial: ${e.source.checkedAt}. Não foi conferida ao vivo nesta busca.`),el('p',e.limitation),el('p',`Endereço: ${e.source.url}`,'url'));
 const inaccessible=el('p',c.unavailable.includes(e.id)?'Você informou que não conseguiu abrir esta fonte. O trecho permanece registrado; confira outra via antes de confiar nele.':'O acesso ao original depende do site de origem.','small');const mark=button(c.unavailable.includes(e.id)?'Fonte voltou a abrir':'Não consegui abrir esta fonte',async()=>{if(c.unavailable.includes(e.id))c.unavailable=c.unavailable.filter(x=>x!==e.id);else c.unavailable.push(e.id);await save();const unavailable=c.unavailable.includes(e.id);inaccessible.textContent=unavailable?'Você informou que não conseguiu abrir esta fonte. O trecho permanece registrado; confira outra via antes de confiar nele.':'O acesso ao original depende do site de origem.';mark.textContent=unavailable?'Fonte voltou a abrir':'Não consegui abrir esta fonte';mark.focus();});d.append(inaccessible,mark);card.append(d);main.append(card);}}
