function readableReport(c){const n=el('article',undefined,'readable-report');n.append(heading(c.title||c.claim||'Rascunho',2),el('p','Contraprova · registro de uma interpretação, sem veredito automático.'));const section=(label,text)=>{n.append(el('h3',label),el('p',text));};section('Frase que eu trouxe',c.input);section('Afirmação investigada',c.claim);if(c.origin==='imported')section('Procedência do registro','Importado: fontes e resumos não autenticados pelo aplicativo.');if(c.result){section('O que encontramos',c.result.summary);section('Universo pesquisado',`Acervo local de sete páginas. Versão ${c.result.corpusVersion}; não é busca ao vivo. Síntese e passagens são paráfrases editoriais.`);for(const [i,e] of c.result.evidence.entries()){section(`Evidência ${i+1}: ${e.source.title}`,`${e.source.author} — ${e.source.url}`);section('Passagem em paráfrase',e.passage);section('Relevância e limite',`${e.relevance} ${e.limitation}`);section('Contexto e datas',`Seção: ${e.section}. Publicação: ${e.source.published}; atualização: ${e.source.updated||'não informada'}; consulta editorial: ${e.source.checkedAt}.`);if(c.unavailable.includes(e.id))section('Acesso à fonte','Informei que não consegui abrir esta fonte.');}section('O que ainda falta saber',c.result.gap);}section('Minha decisão',decisionLabels[c.decision]);section('Minha justificativa',c.reason||'Não registrada.');section('Registro',`${c.createdAt} / ${c.updatedAt}`);return n;}
function exportsFor(c,legacy=false){if(!c)return;const text=legacy?reportMarkdown(c):markdown(c);const report=legacy?el('pre',text,'report'):readableReport(c);const json=()=>download(JSON.stringify(legacy?envelope([c]):bundle([c]),null,2),'contraprova.json','application/json');const md=()=>download(text,'contraprova.md','text/markdown');const print=()=>{document.querySelector('#print-report').replaceChildren(legacy?el('pre',text):readableReport(c));window.print();};showModal(legacy?'Registro preservado da versão 0.1':'Relatório da investigação',[actions(button('Exportar JSON',json),button('Exportar Markdown',md),button('Imprimir / salvar PDF',print)),report]);}
